export type { Database, Json } from "./database";
export * from "./schemas";
export * from "./utility";

/** Nominal/branded primitive, e.g. `Brand<string, "UserId">`. */
export type Brand<T, B extends string> = T & { readonly __brand: B };

/** Flatten an intersection so editor hovers show a clean object. */
export type Prettify<T> = { [K in keyof T]: T[K] } & {};

export type Maybe<T> = T | null | undefined;
export type Nullable<T> = T | null;
export type Awaitable<T> = T | Promise<T>;
export type ValueOf<T> = T[keyof T];

/** Recursively make every property optional. */
export type DeepPartial<T> = T extends object ? { [K in keyof T]?: DeepPartial<T[K]> } : T;

/** Make selected keys required. */
export type RequireKeys<T, K extends keyof T> = Prettify<T & { [P in K]-?: T[P] }>;

/** Make selected keys optional. */
export type OptionalKeys<T, K extends keyof T> = Prettify<Omit<T, K> & { [P in K]?: T[P] }>;

import { z } from "zod";

/** Shared Zod schemas reused across apps and packages. */

export const emailSchema = z.email();
export const uuidSchema = z.uuid();
export const slugSchema = z.string().regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/, "must be kebab-case");

export const idSchema = z.object({ id: uuidSchema });
export type Id = z.infer<typeof idSchema>;

export const paginationSchema = z.object({
  page: z.coerce.number().int().min(1).default(1),
  pageSize: z.coerce.number().int().min(1).max(100).default(20),
});
export type Pagination = z.infer<typeof paginationSchema>;

/**
 * Project database types. Replace with your generated types — Supabase's
 * `supabase gen types typescript`, an ORM's inferred types, etc. Until a schema
 * is linked this empty placeholder keeps imports resolving.
 */
export type Database = Record<string, never>;

export type Json = string | number | boolean | null | { [key: string]: Json | undefined } | Json[];
